snippets.javascript:
// Projects, with their teams and attached papers. No API key needed.
const res = await fetch(
  "https://dashboard.all-ai-network.org/api/public/chapter/{slug}/bundle"
);
const { projects } = await res.json();

for (const p of projects) {
  const team = p.members.map((m) => m.name).join(", ");
  const paper = p.files.find((f) => f.kind === "paper");
  console.log(p.year, p.title, "—", team, paper?.url ?? "");
}

