// Merged curriculum graph: shared base tree + this chapter's nodes.
const res = await fetch(
  "https://dashboard.all-ai-network.org/api/public/learning-tree/{slug}"
);
const { nodes, edges } = await res.json();

// nodes carry pos_x/pos_y when an officer has arranged them —
// honour those and only auto-layout the ones without.
const pinned = nodes.filter((n) => n.pos_x != null && n.pos_y != null);
console.log(`${nodes.length} nodes, ${pinned.length} hand-placed`);

